def count_palindrome_words(s):
    count = 0
    for w in s.split():
        cleaned = ''.join(c.lower() for c in w if c.isalnum())
        if cleaned and cleaned == cleaned[::-1]:
            count += 1
    return count

public boolean isPerfectSquare(int n) {
    if (n < 0) return false;
    int root = (int) Math.sqrt(n);
    return root * root == n || (root + 1) * (root + 1) == n;
}

def factorial(n):
    if n < 0:
        raise ValueError('n must be non-negative')
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

int sum_even(int *arr, int len) {
    int sum = 0;
    for (int i = 0; i < len; i++) {
        if (arr[i] % 2 == 0) sum += arr[i];
    }
    return sum;
}
